VST3PlusVocalsSafeV2Editor::VST3PlusVocalsSafeV2Editor(VST3PlusVocalsSafeV2Processor&x):AudioProcessorEditor(&x),p(x){setSize(1120,720);for(auto*b:{&load,&match})addAndMakeVisible(*b);for(auto*l:{&file,&status,&mainR,&dblR,&adR}){addAndMakeVisible(*l);l->setColour(juce::Label::textColourId,juce::Colours::white);}file.setText("No vocal WAV loaded",juce::dontSendNotification);status.setText("Reference matcher ready",juce::dontSendNotification);const char*n[]={"Comp","Sat","Air","Reverb","Delay","Level","Width","Timing","Reverb","Delay","Level","Width","Dist","Reverb","Delay","Level","Input","Dry/Wet","Output"};for(int i=0;i<VST3PlusVocalsSafeV2Processor::paramCount;++i)addK(n[i],(VST3PlusVocalsSafeV2Processor::Param)i);load.onClick=[this]{chooser=std::make_unique<juce::FileChooser>("Choose isolated vocal WAV",juce::File{},"*.wav");chooser->launchAsync(juce::FileBrowserComponent::openMode|juce::FileBrowserComponent::canSelectFiles,[this](const juce::FileChooser&f){auto q=f.getResult();if(q.existsAsFile()){ref=q;file.setText("Loaded: "+q.getFileName(),juce::dontSendNotification);status.setText("Press ANALYSE + BUILD CHAIN",juce::dontSendNotification);}});};match.onClick=[this]{analyse();};startTimerHz(12);}
void VST3PlusVocalsSafeV2Editor::addK(const char*n,VST3PlusVocalsSafeV2Processor::Param pm){auto q=std::make_unique<K>();q->pm=pm;q->l.setText(n,juce::dontSendNotification);q->l.setJustificationType(juce::Justification::centred);q->l.setColour(juce::Label::textColourId,juce::Colours::white);q->s.setSliderStyle(juce::Slider::RotaryHorizontalVerticalDrag);q->s.setTextBoxStyle(juce::Slider::TextBoxBelow,false,58,17);q->s.setRange(VST3PlusVocalsSafeV2Processor::mins[pm],VST3PlusVocalsSafeV2Processor::maxs[pm],.1);q->s.setValue(p.getParam(pm),juce::dontSendNotification);q->s.onValueChange=[this,ptr=q.get()]{p.setParam(ptr->pm,(float)ptr->s.getValue());};addAndMakeVisible(q->l);addAndMakeVisible(q->s);k.push_back(std::move(q));}
void VST3PlusVocalsSafeV2Editor::timerCallback(){for(auto&q:k)if(!q->s.isMouseButtonDown())q->s.setValue(p.getParam(q->pm),juce::dontSendNotification);repaint();}
void VST3PlusVocalsSafeV2Editor::analyse(){if(!ref.existsAsFile()){status.setText("Load a WAV first",juce::dontSendNotification);return;}juce::WavAudioFormat fmt;std::unique_ptr<juce::AudioFormatReader>r(fmt.createReaderFor(new juce::FileInputStream(ref),true));if(!r){status.setText("WAV decode failed",juce::dontSendNotification);return;}int n=(int)juce::jmin<juce::int64>(r->lengthInSamples,(juce::int64)(r->sampleRate*90.0));int ch=juce::jlimit(1,2,(int)r->numChannels);if(n<=0)return;juce::AudioBuffer<float>a(ch,n);if(!r->read(&a,0,n,0,true,true)){status.setText("WAV read failed",juce::dontSendNotification);return;}double sq=0,diff=0,side=0,mid=0;float peak=0;long long count=0;for(int c=0;c<ch;++c){auto*x=a.getReadPointer(c);float prev=0;for(int i=0;i<n;++i){float v=x[i];sq+=(double)v*v;float d=v-prev;diff+=(double)d*d;prev=v;peak=juce::jmax(peak,std::abs(v));++count;}}if(ch==2){auto*l=a.getReadPointer(0);auto*rr=a.getReadPointer(1);for(int i=0;i<n;++i){float m=.5f*(l[i]+rr[i]),s=.5f*(l[i]-rr[i]);mid+=(double)m*m;side+=(double)s*s;}}double rms=std::sqrt(sq/juce::jmax<long long>(1,count)),crest=peak/juce::jmax(1e-7,rms),bright=std::sqrt(diff/juce::jmax<long long>(1,count))/juce::jmax(1e-7,rms),width=ch==2?std::sqrt(side/juce::jmax(1.0,mid)):0;float comp=juce::jlimit(20.f,70.f,(float)(68-crest*7)),air=juce::jlimit(8.f,68.f,(float)(bright*30)),sat=juce::jlimit(5.f,45.f,(float)(34/juce::jmax(1.0,crest))),rev=juce::jlimit(8.f,38.f,(float)(12+width*22)),del=juce::jlimit(4.f,26.f,(float)(6+width*15)),dw=juce::jlimit(105.f,190.f,(float)(120+width*65));p.setParam(VST3PlusVocalsSafeV2Processor::mainComp,comp);p.setParam(VST3PlusVocalsSafeV2Processor::mainSat,sat);p.setParam(VST3PlusVocalsSafeV2Processor::mainAir,air);p.setParam(VST3PlusVocalsSafeV2Processor::mainRev,rev);p.setParam(VST3PlusVocalsSafeV2Processor::mainDelay,del);p.setParam(VST3PlusVocalsSafeV2Processor::dblWidth,dw);p.setParam(VST3PlusVocalsSafeV2Processor::dblTime,juce::jlimit(10.f,38.f,(float)(15+width*20)));p.setParam(VST3PlusVocalsSafeV2Processor::dblRev,juce::jlimit(10.f,42.f,rev+6));p.setParam(VST3PlusVocalsSafeV2Processor::dblDelay,juce::jlimit(8.f,32.f,del+7));p.setParam(VST3PlusVocalsSafeV2Processor::dblLevel,juce::jlimit(-18.f,-8.f,(float)(-15+width*6)));p.setParam(VST3PlusVocalsSafeV2Processor::adWidth,juce::jlimit(125.f,195.f,dw+12));p.setParam(VST3PlusVocalsSafeV2Processor::adDist,juce::jlimit(10.f,48.f,sat+10));p.setParam(VST3PlusVocalsSafeV2Processor::adRev,juce::jlimit(18.f,55.f,rev+15));p.setParam(VST3PlusVocalsSafeV2Processor::adDelay,juce::jlimit(16.f,48.f,del+18));p.setParam(VST3PlusVocalsSafeV2Processor::adLevel,juce::jlimit(-21.f,-11.f,(float)(-18+width*5)));mainR.setText("MAIN matched: dynamics / sat / air / space",juce::dontSendNotification);dblR.setText("DOUBLES matched: width / timing / space",juce::dontSendNotification);adR.setText("ADLIBS matched: width / distortion / delay",juce::dontSendNotification);status.setText("REFERENCE CHAIN APPLIED",juce::dontSendNotification);}
void VST3PlusVocalsSafeV2Editor::paint(juce::Graphics&g){auto pc=juce::Colour(0xff8e5cff);g.fillAll(juce::Colour(0xff080a12));g.setColour(pc);g.fillRect(0,0,getWidth(),5);g.setColour(juce::Colours::white);g.setFont(28.f);g.drawText("VST3+Vocals SAFE V2",20,14,430,40,juce::Justification::centredLeft);g.setColour(juce::Colour(0xffbdaaff));g.setFont(14.f);g.drawText("WAV Vocal Reference Matcher • by 29YURO",22,52,450,20,juce::Justification::centredLeft);auto box=[&](int x,int y,int w,int h,const char*t){g.setColour(juce::Colour(0xff111522));g.fillRoundedRectangle((float)x,(float)y,(float)w,(float)h,10);g.setColour(juce::Colour(0xff30264a));g.drawRoundedRectangle(juce::Rectangle<float>((float)x,(float)y,(float)w,(float)h),10,1);g.setColour(pc);g.drawText(t,x+12,y+7,w-24,20,juce::Justification::centredLeft);};box(18,82,1084,125,"REFERENCE VOCAL");box(18,222,1084,140,"MAIN VOCAL");box(18,377,1084,140,"DOUBLES");box(18,532,1084,140,"ADLIBS + MASTER");g.setColour(juce::Colour(0xff202638));g.fillRect(28,690,1050,9);g.setColour(pc);g.fillRect(28,690,(int)(1050*juce::jlimit(0.f,1.f,p.meter)),9);}
void VST3PlusVocalsSafeV2Editor::resized(){load.setBounds(32,116,205,34);match.setBounds(247,116,245,34);file.setBounds(510,110,565,24);status.setBounds(510,139,565,24);mainR.setBounds(32,173,330,22);dblR.setBounds(370,173,330,22);adR.setBounds(708,173,365,22);int i=0;auto row=[&](int y,int count){int x=32;for(int j=0;j<count;++j,++i){k[i]->l.setBounds(x,y,105,18);k[i]->s.setBounds(x,y+18,105,92);x+=116;}};row(246,6);row(401,5);row(556,5);for(;i<(int)k.size();++i){int x=730+(i-16)*116;k[i]->l.setBounds(x,556,105,18);k[i]->s.setBounds(x,574,105,92);}}
